var buyers=accounts.filter(function(a){return String(a.username).indexOf('wxh5_')===0&&a.wechat_openid&&!a.service_provider;});
var staff=accounts.filter(function(a){return a.service_provider&&a.service_provider.can_accept_order&&a.service_provider.service_status==='ACTIVE';})[0];check(buyers.length>1&&staff,'Missing test actors');var buyer=buyers[0].id,other=buyers[1].id;
var products=query('BundleExistingProduct','query BundleExistingProduct{public_class(where:{_eq:{text_operand:{left_operand:{column:product_kind},right_operand:{literal:"CHILD_EDUCATION_BUNDLE"}}}},limit:2){id}}').public_class;check(products.length<2,'Unique product');
var product=products[0]||query('BundleTestProduct','mutation BundleTestProduct($o:public_class_insert_input!){insert_public_class_one(object:$o){id}}',{o:{title:'自动回滚-孩子教育课程包',product_kind:'CHILD_EDUCATION_BUNDLE',status:'PUBLISHED',organizer_id:staff.service_provider.id,registration_fee:688,capacity:0,reserved_count:0,revision:0,notice:JSON.stringify({version:1,courseIds:[7,8,9,10,11,12,13,14]})}}).insert_public_class_one;
